import sys
import heapq

def find(x):
    while x in parent:
        if parent[x] in parent:
            parent[x] = parent[parent[x]]
        x = parent[x]
    return x

def union(x, y):
    rootX = find(x)
    rootY = find(y)
    if rootX != rootY:
        if rank[rootX] > rank[rootY]:
            parent[rootY] = rootX
        elif rank[rootX] < rank[rootY]:
            parent[rootX] = rootY
        else:
            parent[rootY] = rootX
            rank[rootX] += 1

def kruskal_with_odd_degrees(edges, n):
    mst_edges = []
    parent.clear()
    rank.clear()
    degrees = [0] * (n + 1)

    for u, v, w in edges:
        rootU = find(u)
        rootV = find(v)
        if rootU != rootV:
            union(u, v)
            mst_edges.append((w, u, v))
            degrees[u] ^= 1
            degrees[v] ^= 1

    odd_nodes = [node for node in range(1, n + 1) if degrees[node] == 1]
    if len(odd_nodes) % 2 != 0:
        return -1

    min_matching_weight = 0
    if len(odd_nodes) > 0:
        min_matching_weight = minimum_weight_perfect_matching(odd_nodes, edges)

    total_weight = sum(w for w, _, _ in mst_edges)
    return total_weight + min_matching_weight

def minimum_weight_perfect_matching(odd_nodes, edges):
    import networkx as nx
    G = nx.Graph()
    for u, v, w in edges:
        if u in odd_nodes and v in odd_nodes:
            G.add_edge(u, v, weight=w)
    matching = nx.algorithms.matching.max_weight_matching(G, maxcardinality=True)
    return sum(G.edges[e]['weight'] for e in matching)

